from __future__ import annotations

import pytest

from llm_worker_pool.domain.token_estimate import (
    CONTEXT_RESERVE_RATIO,
    _CHARS_PER_TOKEN,
    estimate_tokens,
    max_chars_for_tokens,
)


def test_estimate_tokens_exact_multiple() -> None:
    text = "abcd" * 3  # 12 chars
    assert estimate_tokens(text) == 3


def test_estimate_tokens_with_remainder() -> None:
    text = "abcde"  # 5 chars
    assert estimate_tokens(text) == 5 // _CHARS_PER_TOKEN


def test_estimate_tokens_empty() -> None:
    assert estimate_tokens("") == 0


def test_max_chars_for_tokens() -> None:
    assert max_chars_for_tokens(10) == 40
    assert max_chars_for_tokens(0) == 0


def test_context_reserve_ratio_value() -> None:
    assert CONTEXT_RESERVE_RATIO == 0.25
